<script setup>
import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import {addToCart} from '../../stores';import api from '../../services/api'
const route=useRoute(),product=ref(null),loading=ref(true)
onMounted(async()=>{try{product.value=(await api.get('/products/'+route.params.slug)).data}catch(e){}finally{loading.value=false}})
</script><template><div v-if="loading" class="py-20 text-center">Loading…</div><div v-else-if="!product" class="py-20 text-center">Product not found.</div><section v-else class="grid gap-10 md:grid-cols-2"><div class="overflow-hidden rounded-3xl bg-slate-100"><img v-if="product.imageUrl" :src="product.imageUrl" class="aspect-square w-full object-cover"/><div v-else class="flex aspect-square items-center justify-center text-slate-300">No image</div></div><div class="py-4"><p class="text-sm font-bold uppercase tracking-wider text-indigo-600">Product</p><h1 class="mt-2 text-4xl font-black">{{product.name}}</h1><p class="mt-5 text-3xl font-black">{{Number(product.price).toLocaleString()}} {{product.currency||'ETB'}}</p><p class="mt-6 leading-7 text-slate-600">{{product.description}}</p><button @click="addToCart(product)" class="mt-8 rounded-xl bg-indigo-600 px-6 py-3 font-bold text-white">Add to cart</button></div></section></template>